          <div className=\"chart-plot\" role=\"img\" aria-label={"'`Линейный график: ${seriesNames.filter((_, i) => visible[i]).join('"', ')}. С "'${start + 1} по 30 октября 2026 года.`}>{visible.some(Boolean) ? <Chart data={chartData}/> : <div className="empty-state"><Text variant="subheader-2">Выберите данные для отображения</Text><Text color="secondary">Нажмите на название ряда над графиком.</Text><Button view="outlined" onClick={() => setVisible([true, true])}>Показать все данные</Button></div>}</div>
